//! Bulk autocorrect regressions.
//!
//! `data/autocorrect_cases.tsv` is generated by
//! `cargo run --release --example make_autocorrect_cases` and contains
//! neighbouring-key, transposition, insertion/deletion and accent typos of
//! dictionary words that the corrector resolves to the intended word.

use type1_core::correction;
use type1_core::dictionary;
use type1_core::layout::LETTERS;
use type1_core::{Action, Engine};

const TEXT: i32 = 0x0000_0001;
const CAP_SENTENCES: i32 = 0x0000_4000;

struct Rng(u64);

impl Rng {
	fn next(&mut self) -> u64 {
		let mut x = self.0;
		x ^= x << 13;
		x ^= x >> 7;
		x ^= x << 17;
		self.0 = x;
		x
	}

	fn below(&mut self, n: usize) -> usize {
		(self.next() % n as u64) as usize
	}
}

fn neighbour(c: char, rng: &mut Rng, order: &[char]) -> char {
	let Some(index) = order.iter().position(|&x| x == c) else {
		return c;
	};
	let next = if rng.below(2) == 0 {
		(index + 1).min(order.len() - 1)
	} else {
		index.saturating_sub(1)
	};
	order[next]
}

fn parse_cases(source: &'static str) -> Vec<(&'static str, &'static str)> {
	source
	.lines()
	.filter_map(|line| {
		let (typed, expected) = line.split_once('\t')?;
		if typed.is_empty() || expected.is_empty() {
			return None;
		}
		Some((typed, expected))
	})
	.collect()
}

fn cases() -> Vec<(&'static str, &'static str)> {
	parse_cases(include_str!("data/autocorrect_cases.tsv"))
}

fn two_key_cases() -> Vec<(&'static str, &'static str)> {
	parse_cases(include_str!("data/two_key_cases.tsv"))
}

fn spelling_cases() -> Vec<(&'static str, &'static str)> {
	parse_cases(include_str!("data/spelling_cases.tsv"))
}

fn best(typed: &str) -> (bool, Option<String>, u8) {
	let suggestion = correction::suggest(typed);
	let best = suggestion.candidates.first();
	(
		suggestion.apply,
		best.map(|candidate| candidate.text.clone()),
		best.map(|candidate| candidate.tier).unwrap_or(0),
	)
}

#[test]
fn thousands_of_typos_reach_the_intended_word() {
	let cases = cases();
	assert!(cases.len() >= 2_000, "only {} cases", cases.len());

	let mut failures = Vec::new();
	let mut two_key = 0usize;
	for (typed, expected) in &cases {
		let (apply, best, tier) = best(typed);
		if tier == 2 {
			two_key += 1;
		}
		if !apply || best.as_deref() != Some(expected) {
			failures.push(format!(
				"{typed} -> {best:?} (apply {apply}), want {expected}"
			));
		}
	}
	assert!(
		two_key >= 25,
		"fixture only has {two_key} two-key cases ({} total)",
		cases.len()
	);
	assert!(
		failures.is_empty(),
		"{} / {} fixture cases failed:\n{}",
		failures.len(),
		cases.len(),
		failures
		. iter()
		.take(25)
		.cloned()
		.collect::<Vec<_>>()
		. join("\n")
	);
}

#[test]
fn named_regressions() {
	let cases = [
		("glnjojr", "bonjour"),
		("bknjpur", "bonjour"),
		("commant", "comment"),
		("ckppsuv", "comment"),
		("roppxjf", "comment"),
		("vqjmd", "t'aime"),
		("geqnvx", "beauté"),
		("secg", "sert"),
		("pa", "la"),
		("pq", "la"),
		("taimx", "t'aime"),
		("taipe", "t'aime"),
		("tset", "test"),
		("bonjor", "bonjour"),
		("ecole", "école"),
		("jai", "j'ai"),
		("lhomme", "l'homme"),
		("daccord", "d'accord"),
		("quil", "qu'il"),
		("jusqua", "jusqu'à"),
		("dous", "doux"),
		("mieu", "mieux"),
		("vou", "vous"),
		("sa", "sa"),
	];

	for (typed, expected) in cases {
		if typed == expected {
			let suggestion = correction::suggest(typed);
			assert!(
				suggestion.candidates.is_empty(),
				"{typed} should be left alone, got {:?}",
				suggestion.candidates.first().map(|c| &c.text)
			);
			continue;
		}
		let (apply, best, _) = best(typed);
		assert!(apply, "{typed} was not applied (best {best:?})");
		assert_eq!(best.as_deref(), Some(expected), "{typed}");
	}
}

#[test]
fn common_words_stay_put() {
	for word in [
		"test", "la", "ma", "bonjour", "maison", "personne", "vraiment", "toutes",
		"comment",
	] {
		let suggestion = correction::suggest(word);
		assert!(
			suggestion.candidates.is_empty(),
			"{word} should be left alone, got {:?}",
			suggestion.candidates.first().map(|c| &c.text)
		);
	}
}

#[test]
fn sentence_initial_capitals_are_preserved() {
	let mut engine = Engine::new();
	engine.set_input_type(TEXT | CAP_SENTENCES, 0);
	for key in ["g", "l", "n", "j", "o", "j", "r"] {
		engine.on_key(key);
	}
	assert_eq!(
		engine.on_key("space"),
		vec![
			Action::DeleteChars(7),
			Action::Commit("Bonjour".into()),
			Action::Commit(" ".into()),
		]
	);
}

#[test]
fn sentence_initial_capitals_from_the_fixture() {
	let cases = cases();
	let mut checked = 0usize;
	for (typed, expected) in cases.iter().step_by(41) {
		if !typed.chars().all(|c| c.is_ascii_lowercase()) {
			continue;
		}
		if checked >= 40 {
			break;
		}
		checked += 1;
		let mut engine = Engine::new();
		engine.set_input_type(TEXT | CAP_SENTENCES, 0);
		for ch in typed.chars() {
			engine.on_key(&ch.to_string());
		}
		let mut chars = expected.chars();
		let capitalized = match chars.next() {
			Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
			None => String::new(),
		};
		assert_eq!(
			engine.on_key("space"),
			vec![
				Action::DeleteChars(typed.chars().count() as u32),
				Action::Commit(capitalized),
				Action::Commit(" ".into()),
			],
			"typing {typed}"
		);
	}
	assert!(checked >= 20, "only {checked} capitalised cases checked");
}

#[test]
fn sentence_initial_common_words_stay_put() {
	let mut engine = Engine::new();
	engine.set_input_type(TEXT | CAP_SENTENCES, 0);
	for key in ["t", "e", "s", "t"] {
		engine.on_key(key);
	}
	assert_eq!(engine.on_key("space"), vec![Action::Commit(" ".into())]);
}

#[test]
fn one_key_candidates_rank_before_two_key_candidates() {
	let suggestion = correction::suggest("emps");
	assert!(suggestion.apply);
	assert_eq!(suggestion.candidates[0].text, "temps");
	assert_eq!(suggestion.candidates[0].tier, 1);
	assert!(
		suggestion.candidates.iter().any(|candidate| candidate.tier == 2),
		"expected a two-key candidate too"
	);
	assert!(
		suggestion
		.candidates
		.windows(2)
		.all(|pair| pair[0].tier <= pair[1].tier),
		"tiers are out of order: {:?}",
		suggestion
		.candidates
		.iter()
		.map(|candidate| (candidate.text.as_str(), candidate.tier))
		.collect::<Vec<_>>()
	);
}

#[test]
fn spelling_and_keyboard_variants_are_both_suggested() {
	let suggestion = correction::suggest("commant");
	assert!(suggestion.apply);
	let texts: Vec<&str> = suggestion
	.candidates
	.iter()
	.map(|candidate| candidate.text.as_str())
	.collect();
	let position = |word: &str| texts.iter().position(|text| *text == word);
	let comment = position("comment").expect("comment");
	let collant = position("collant").expect("collant");
	assert!(comment < collant, "unexpected order: {texts:?}");
}

#[test]
fn spelling_variant_is_offered_before_the_keyboard_variant() {
	let mut engine = Engine::new();
	engine.set_input_type(TEXT, 0);
	for key in ["c", "o", "m", "m", "a", "n", "t"] {
		engine.on_key(key);
	}
	let json: serde_json::Value = serde_json::from_str(&engine.render_json()).unwrap();
	let suggestions: Vec<&str> = json["suggestions"]
	.as_array()
	.unwrap()
	.iter()
	.map(|value| value.as_str().unwrap())
	.collect();
	assert_eq!(suggestions[0], "comment");
	assert!(suggestions.contains(&"collant"), "suggestions: {suggestions:?}");
	assert_eq!(
		engine.on_key("space"),
		vec![
			Action::DeleteChars(7),
			Action::Commit("comment".into()),
			Action::Commit(" ".into()),
		]
	);
}

#[test]
fn two_key_typo_is_suggested_and_applied() {
	let mut engine = Engine::new();
	engine.set_input_type(TEXT, 0);
	for key in ["b", "k", "n", "j", "p", "u", "r"] {
		engine.on_key(key);
	}
	let json: serde_json::Value = serde_json::from_str(&engine.render_json()).unwrap();
	assert_eq!(json["suggestions"][0], "bonjour");
	assert_eq!(
		engine.on_key("space"),
		vec![
			Action::DeleteChars(7),
			Action::Commit("bonjour".into()),
			Action::Commit(" ".into()),
		]
	);
}

fn check_rule_cases(cases: &[(&str, &str)]) -> (Vec<String>, usize) {
	let mut failures = Vec::new();
	let mut applied = 0usize;
	for (typed, expected) in cases {
		let suggestion = correction::suggest(typed);
		let tier_ordered = suggestion
		.candidates
		.windows(2)
		.all(|pair| pair[0].tier <= pair[1].tier);
		let found = suggestion
		.candidates
		.iter()
		.position(|candidate| candidate.text == *expected);
		let visible = found.is_some_and(|index| {
			index < 3 && suggestion.candidates[index].tier == 2
		});
		if !tier_ordered || !visible {
			failures.push(format!(
				"{typed} -> want {expected}, got {:?}",
				suggestion
				.candidates
				.iter()
				.map(|candidate| (candidate.text.as_str(), candidate.tier))
				.collect::<Vec<_>>()
			));
		}
		if suggestion.apply {
			applied += 1;
		}
	}
	(failures, applied)
}

#[test]
fn thousands_of_two_key_typos_are_suggested() {
	let cases = two_key_cases();
	assert!(cases.len() >= 2_000, "only {} two-key cases", cases.len());
	let (failures, applied) = check_rule_cases(&cases);
	assert!(
		failures.is_empty(),
		"{} / {} two-key cases failed:\n{}",
		failures.len(),
		cases.len(),
		failures
		. iter()
		.take(20)
		.cloned()
		.collect::<Vec<_>>()
		. join("\n")
	);
	assert!(applied >= 100, "only {applied} two-key cases auto-applied");
}

#[test]
fn thousands_of_spelling_variants_are_suggested() {
	let cases = spelling_cases();
	assert!(cases.len() >= 2_000, "only {} spelling cases", cases.len());
	let (failures, _) = check_rule_cases(&cases);
	assert!(
		failures.is_empty(),
		"{} / {} spelling cases failed:\n{}",
		failures.len(),
		cases.len(),
		failures
		. iter()
		.take(20)
		.cloned()
		.collect::<Vec<_>>()
		. join("\n")
	);
}

#[test]
fn ambiguous_spelling_pairs_stay_suggestions() {
	for word in ["avaiw", "veub"] {
		let suggestion = correction::suggest(word);
		assert!(!suggestion.apply, "{word} should stay a suggestion");
		assert!(
			!suggestion.candidates.is_empty(),
			"{word} should still be suggested"
		);
	}
}

#[test]
fn very_last_resort_finds_the_closest_word() {
	let suggestion = correction::suggest("bodjmur");
	assert!(!suggestion.apply);
	assert_eq!(suggestion.candidates[0].text, "bonjour");
	assert_eq!(suggestion.candidates[0].tier, 3);
}

#[test]
fn last_resort_does_not_run_when_closer_rules_match() {
	let suggestion = correction::suggest("emps");
	assert!(
		suggestion.candidates.iter().all(|candidate| candidate.tier < 3),
		"unexpected last-resort candidates: {:?}",
		suggestion
		.candidates
		.iter()
		.map(|candidate| (candidate.text.as_str(), candidate.tier))
		.collect::<Vec<_>>()
	);
}

#[test]
fn very_last_resort_is_offered_but_not_applied() {
	let mut engine = Engine::new();
	engine.set_input_type(TEXT, 0);
	for key in ["b", "o", "d", "j", "m", "u", "r"] {
		engine.on_key(key);
	}
	let json: serde_json::Value = serde_json::from_str(&engine.render_json()).unwrap();
	assert_eq!(json["suggestions"][0], "bonjour");
	assert_eq!(engine.on_key("space"), vec![Action::Commit(" ".into())]);
}

#[test]
fn held_out_neighbour_typos_stay_above_the_floor() {
	let order: Vec<char> = LETTERS
	.iter()
	.filter_map(|letter| letter.id.chars().next())
	.collect();
	let pool: Vec<&'static str> = dictionary::words()
	.iter()
	.filter(|word| {
		let len = word.text.chars().count();
		(4..=9).contains(&len) && word.log_freq > 4.0 && !word.text.contains('\'')
	})
	.map(|word| word.text)
	.collect();

	let mut rng = Rng(0x1234_5678_9abc_def0);
	let mut total = 0usize;
	let mut top1 = 0usize;
	let mut applied = 0usize;
	for _ in 0..900 {
		let word = pool[rng.below(pool.len())];
		let mut chars: Vec<char> = word.chars().collect();
		let edits = 1 + rng.below(2);
		for _ in 0..edits {
			let i = rng.below(chars.len());
			chars[i] = neighbour(chars[i], &mut rng, &order);
		}
		let typed: String = chars.into_iter().collect();
		if typed == word || dictionary::exact(&typed).is_some() || typed.is_empty() {
			continue;
		}
		total += 1;
		let (apply, best, _) = best(&typed);
		if best.as_deref() == Some(word) {
			top1 += 1;
			if apply {
				applied += 1;
			}
		}
	}
	let accuracy = top1 as f64 * 100.0 / total.max(1) as f64;
	let apply_rate = applied as f64 * 100.0 / total.max(1) as f64;
	assert!(
		total >= 500,
		"only {total} usable held-out cases (accuracy {accuracy:.1}%)"
	);
	assert!(
		accuracy >= 70.0,
		"top-1 accuracy fell to {accuracy:.1}% ({top1} / {total})"
	);
	assert!(
		apply_rate >= 65.0,
		"auto-apply rate fell to {apply_rate:.1}% ({applied} / {total})"
	);
}
